function escapeXml(s){ return String(s).replace(/[<>&"]/g, function(c){ return c==="<"?"&lt;":c===">"?"&gt;":c==="&"?"&amp;":"&quot;"; }); }
function buildOgSVG(opts){
  var w = opts.w || 1200, h = opts.h || 630;
  var bg = opts.bg || "#0A0A0B", fg = opts.fg || "#FFFFFF", accent = opts.accent || "#5E6AD2";
  var title = escapeXml(opts.title || "Title"), sub = escapeXml(opts.subtitle || ""), brand = escapeXml(opts.brand || "");
  return '<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">' +
    '<rect width="100%" height="100%" fill="'+bg+'"/>' +
    '<rect x="64" y="64" width="12" height="'+(h-128)+'" fill="'+accent+'"/>' +
    '<text x="110" y="'+(h/2 - (sub?40:0))+'" fill="'+fg+'" font-family="sans-serif" font-size="72" font-weight="700">'+title+'</text>' +
    (sub ? '<text x="110" y="'+(h/2+50)+'" fill="'+fg+'" font-family="sans-serif" font-size="36" opacity="0.8">'+sub+'</text>' : '') +
    (brand ? '<text x="110" y="'+(h-70)+'" fill="'+accent+'" font-family="sans-serif" font-size="28" font-weight="700">'+brand+'</text>' : '') +
    '</svg>';
}
var EXPORTS = { buildOgSVG: buildOgSVG };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OgImageForgePure = EXPORTS; }
